import {
  Container,
  Typography,
  Grid,
  Card,
  CardMedia,
  CardContent,
  Button,
  Box,
  Chip,
} from "@mui/material";

import {
  useEffect,
  useState,
} from "react";

import {
  Link,
} from "react-router-dom";

import API from "../services/api";

export default function MyBlogs() {

  const [blogs, setBlogs] =
    useState([]);

  const fetchMyBlogs = async () => {

    try {

      const response = await API.get(
        "/blogs/myblogs"
      );

      setBlogs(response.data);

    } catch (error) {

      console.log(error);
    }
  };

  useEffect(() => {

    fetchMyBlogs();

  }, []);

  const handleDelete = async (id) => {

    const confirmDelete =
      window.confirm(
        "Move blog to recycle bin?"
      );

    if (!confirmDelete) return;

    try {

      await API.delete(
        `/blogs/${id}`
      );

      fetchMyBlogs();

    } catch (error) {

      console.log(error);
    }
  };

  return (

    <Container sx={{ py: 5 }}>

      {/* PAGE HEADING */}

      <Box sx={{ mb: 5 }}>

        <Typography
          variant="h3"
          fontWeight={800}
        >
          My Blogs
        </Typography>

        <Typography
          color="text.secondary"
        >
          Manage your published blogs
        </Typography>

      </Box>

      {/* EMPTY STATE */}

      {blogs.length === 0 && (

        <Box
          sx={{
            py: 10,
            textAlign: "center",
          }}
        >

          <Typography
            variant="h5"
            fontWeight={700}
          >
            No blogs yet
          </Typography>

          <Typography
            color="text.secondary"
            sx={{ mt: 1 }}
          >
            Start creating amazing blogs.
          </Typography>

        </Box>
      )}

      {/* BLOG GRID */}

      <Grid container spacing={4}>

        {blogs.map((blog) => (

          <Grid
            item
            xs={12}
            sm={6}
            md={4}
            key={blog._id}
          >

            <Card
              sx={{
                height: "100%",
                borderRadius: 4,
                overflow: "hidden",
                transition: "0.3s",

                "&:hover": {
                  transform:
                    "translateY(-10px)",
                  boxShadow: 8,
                },
              }}
            >

              <CardMedia
                component="img"
                height="220"
                image={blog.image}
                alt={blog.title}
              />

              <CardContent>

                <Chip
                  label={blog.category}
                  color="primary"
                  size="small"
                  sx={{ mb: 2 }}
                />

                <Typography
                  variant="h5"
                  fontWeight={700}
                  gutterBottom
                >
                  {blog.title}
                </Typography>

                <Typography
                  variant="body2"
                  color="text.secondary"
                  sx={{
                    lineHeight: 1.8,
                    mb: 3,
                  }}
                >
                  {blog.content.slice(
                    0,
                    100
                  )}...
                </Typography>

                <Box
                  sx={{
                    display: "flex",
                    gap: 2,
                  }}
                >

                  <Button
                    component={Link}
                    to={`/edit-blog/${blog._id}`}
                    variant="contained"
                    fullWidth
                  >
                    Edit
                  </Button>

                  <Button
                    variant="outlined"
                    color="error"
                    fullWidth
                    onClick={() =>
                      handleDelete(
                        blog._id
                      )
                    }
                  >
                    Delete
                  </Button>

                </Box>

              </CardContent>

            </Card>

          </Grid>
        ))}
      </Grid>

    </Container>
  );
}
